\toprule
Eval.\ Granularity & Seed & Bal.\ Acc.\ (\%) \\
\midrule
Step-level & 42 & 57.06 \\
(same-episode & 43 & 63.99 \\
leakage) & 44 & 55.43 \\
 & 45 & 56.14 \\
 & 46 & 55.45 \\
 & 47 & 50.08 \\
 & 48 & 48.03 \\
 & 49 & 59.30 \\
\cmidrule{2-3}
 & Mean$\pm$std & $54.1 \pm 5.4$ \\
\midrule
Episode-level & 42 & 48.1 \\
(held-out & 43 & 47.9 \\
episodes) & 44 & 49.6 \\
